<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/app/bootstrap.php';
require_once dirname(__DIR__).'/includes/app/savings_realization.php';
require_permission('savings.view');

$id=query_int('id');
$selected=$id?savings_realization_find_opportunity($id):savings_realization_default_opportunity();
if($id&&!$selected){flash('error','The savings opportunity is outside the active company scope.');redirect_to(app_url('savings-realization.php'));}
$opportunities=savings_realization_opportunities();
$baselines=$selected?savings_realization_baselines((int)$selected['id']):[];
$periods=$selected?savings_realization_periods((int)$selected['id']):[];
$periodId=query_int('period_id');
$activePeriod=$periodId?savings_realization_find_period($periodId):($periods[0]??null);
if($activePeriod&&$selected&&(int)$activePeriod['opportunity_id']!==(int)$selected['id'])$activePeriod=null;
$evidence=$selected?savings_realization_evidence((int)$selected['id']):[];
$validations=$selected?savings_realization_validations((int)$selected['id']):[];
$leakage=$selected?savings_realization_leakage((int)$selected['id']):[];
$events=$selected?savings_realization_events((int)$selected['id']):[];
$metrics=savings_realization_metrics($selected);
if(query_string('export')==='csv'&&$selected)savings_realization_export_csv($selected,$metrics,$baselines,$periods,$evidence,$validations,$leakage,$events);
$prompt='Review savings realization and finance governance for '.($selected['opportunity_number']??'the selected opportunity').'. Evaluate approved baselines, periodized hard savings, cost avoidance, recoveries, working capital, implementation costs, leakage, transaction evidence, finance validation, forecast accuracy, value at risk, and corrective actions.';
$actions='<a class="button ghost" href="'.h(app_url('savings.php')).'">Savings Pipeline</a><a class="button ghost" href="'.h(app_url('fulfillment.php')).'">Fulfillment Evidence</a><a class="button ghost" href="'.h(app_url('inventory-operations.php')).'">Inventory Evidence</a>';
if($selected&&can('reports.export'))$actions.='<a class="button secondary" href="'.h(app_url('savings-realization.php?id='.(int)$selected['id'].'&export=csv')).'">Export Realization</a>';
$actions.='<a class="button primary" href="'.h(app_url('agent.php?prompt='.rawurlencode($prompt))).'">Analyze in Agent</a>';
render_app_start('Savings Realization, Finance Validation & Procurement Value Governance','savings','Finance-defensible procurement value','Convert sourcing, contract, purchasing, invoice, inventory, and recovery evidence into periodized, independently validated net value.',$actions);
require dirname(__DIR__).'/includes/app/savings_realization_view_styles.php';
?>
